/**
 * Pure fold of one session log into {@link SessionFacts}. Every field comes
 * from a named session event: the identity group from `environment/run` and
 * `request/header`, the outcome group from `goal/change`, the five
 * `verification/*` events and `budget/breach`, the efficiency group from
 * `turn/start`, `step/start`, and the usage of `assistant/message`, and the
 * tool group from `tool/call` and `tool/result`.
 *
 * The outcome group is decided by the folds that already own those streams —
 * `foldTrajectoryReward`, `foldVerification`, and `foldGoal` — so the events
 * they read are kept in the accumulator and refolded whenever one arrives.
 *
 * @module @deepseek-ai/dsh-scorekeeper
 */

import { decodeEnvironmentRun } from '@deepseek-ai/dsh-environments'
import { foldGoal } from '@deepseek-ai/dsh-goal'
import type { SessionEvent, SessionHeader } from '@deepseek-ai/dsh-session'
// Type-only: the `budget/breach` SessionEventMap merge this fold reads.
import type {} from '@deepseek-ai/dsh-budget-policy'
import { TOOL_TIMEOUT } from '@deepseek-ai/dsh-tool-call-timeout-policy'
import { TOOL_ABORTED, TOOL_ABORTED_BEFORE_DISPATCH } from '@deepseek-ai/dsh-tools'
import { foldTrajectoryReward } from '@deepseek-ai/dsh-trajectories'
import { foldVerification } from '@deepseek-ai/dsh-verification'
import type {
  SessionFacts,
  SessionFactsEfficiency,
  SessionFactsIdentity,
  SessionFactsOutcome,
  SessionFactsRecord,
  SessionFactsTools,
} from './types.ts'

/** The outcome group of a log that recorded no goal and no standard. */
const EMPTY_OUTCOME: SessionFactsOutcome = {
  reward: null,
  rewardBasis: 'none',
  certified: false,
  runsRecorded: 0,
  attempts: 0,
  directives: 0,
  relaxations: 0,
  goalRoundsStarted: 0,
}

/** The facts of the empty log. */
const EMPTY_FACTS: SessionFacts = {
  identity: {},
  outcome: EMPTY_OUTCOME,
  efficiency: {
    turns: 0,
    steps: 0,
    inputTokens: 0,
    outputTokens: 0,
    cacheReadTokens: 0,
    cacheWriteTokens: 0,
    reasoningTokens: 0,
    wallMs: 0,
  },
  tools: { toolCalls: 0, toolCallsByName: {}, toolErrors: 0, toolTimeouts: 0, toolAborts: 0 },
}

/**
 * Accumulator of the session-facts fold. Plain JSON throughout, so the
 * projection registry can persist and restore it.
 */
export interface SessionFactsState {
  /** Facts covering every event folded so far. */
  readonly facts: SessionFacts
  /** The goal, verification, and budget events the outcome group refolds from. */
  readonly outcomeEvents: readonly SessionEvent[]
  /** Time of the first folded event, absent for the empty log. */
  readonly firstTime?: number
}

/**
 * Build an empty accumulator.
 * @returns state whose facts are those of the empty log.
 */
export function emptySessionFactsState(): SessionFactsState {
  return { facts: EMPTY_FACTS, outcomeEvents: [] }
}

/** Whether the outcome group folds from this event. */
function isOutcomeEvent(event: SessionEvent): boolean {
  switch (event.type) {
    case 'goal/change':
    case 'verification/standard':
    case 'verification/relaxation':
    case 'verification/run':
    case 'verification/certificate':
    case 'verification/directive':
    case 'budget/breach':
      return true
    // An admitted continuation round is a user message; the goal fold counts it.
    case 'user/message':
      return event.data.source.kind === 'goal'
    default:
      return false
  }
}

/** The cap of the last recorded breach, absent when the events hold none. */
function breachCap(events: readonly SessionEvent[]): Pick<SessionFactsOutcome, 'budgetBreachCap'> {
  let cap: SessionFactsOutcome['budgetBreachCap']
  for (const event of events) {
    if (event.type === 'budget/breach') cap = event.data.cap
  }
  return cap === undefined ? {} : { budgetBreachCap: cap }
}

/**
 * Fold the outcome group from the goal, verification, and budget events.
 * @param events - the kept outcome events in sequence order.
 * @returns the outcome group.
 * @throws when a kept event violates the strict goal or verification stream.
 */
function foldOutcome(events: readonly SessionEvent[]): SessionFactsOutcome {
  const reward = foldTrajectoryReward(events)
  const verification = foldVerification(events)
  const goal = foldGoal(events)
  return {
    reward: reward.outcome,
    rewardBasis: reward.basis,
    certified: verification.certificate !== undefined,
    ...verification.certificate === undefined
      ? {}
      : { certificateRevision: verification.certificate.standard.revision },
    runsRecorded: verification.runsRecorded,
    attempts: verification.lastRun?.attempt ?? 0,
    directives: reward.directives,
    relaxations: reward.relaxations,
    ...goal.goal === undefined ? {} : { goalPhase: goal.goal.phase, goalRoundsCap: goal.goal.maxGoalRounds },
    goalRoundsStarted: goal.roundsStarted,
    ...breachCap(events),
  }
}

/** Replace the identity group. */
function withIdentity(state: SessionFactsState, identity: SessionFactsIdentity): SessionFactsState {
  return { ...state, facts: { ...state.facts, identity: { ...state.facts.identity, ...identity } } }
}

/** Replace the efficiency group. */
function withEfficiency(state: SessionFactsState, efficiency: Partial<SessionFactsEfficiency>): SessionFactsState {
  return { ...state, facts: { ...state.facts, efficiency: { ...state.facts.efficiency, ...efficiency } } }
}

/** Replace the tool group. */
function withTools(state: SessionFactsState, tools: Partial<SessionFactsTools>): SessionFactsState {
  return { ...state, facts: { ...state.facts, tools: { ...state.facts.tools, ...tools } } }
}

/** Extend the log's time span with one event, so `wallMs` spans first to last. */
function withEventTime(state: SessionFactsState, event: SessionEvent): SessionFactsState {
  const firstTime = state.firstTime ?? event.time
  return { ...withEfficiency(state, { wallMs: event.time - firstTime }), firstTime }
}

/** Add one run stamp's fields to the identity group. */
function withStamp(state: SessionFactsState, event: SessionEvent<'environment/run'>): SessionFactsState {
  // The durable boundary validates the stamp; a malformed one fails the fold loudly.
  const stamp = decodeEnvironmentRun(event.data)
  /* v8 ignore next -- the event's declared payload always identifies itself as a run stamp. */
  if (stamp === undefined) return state
  return withIdentity(state, {
    environment: {
      environmentId: stamp.environmentId,
      environmentKind: stamp.environmentKind,
      heldOut: stamp.heldOut,
      repetition: stamp.repetition,
      ...stamp.group === undefined ? {} : { group: stamp.group },
      contentSha256: stamp.contentSha256,
      provider: stamp.model.provider,
      model: stamp.model.model,
      isolation: stamp.isolation,
    },
  })
}

/**
 * Add one assistant message's provider accounting. Only `assistant/message`
 * carries a step's final usage, so the earlier `assistant/chunk` sample for the
 * same step is deliberately ignored rather than counted twice.
 */
function withUsage(state: SessionFactsState, event: SessionEvent<'assistant/message'>): SessionFactsState {
  const usage = event.data.usage
  if (usage === undefined) return state
  const totals = state.facts.efficiency
  return withEfficiency(state, {
    inputTokens: totals.inputTokens + usage.inputTokens,
    outputTokens: totals.outputTokens + usage.outputTokens,
    cacheReadTokens: totals.cacheReadTokens + (usage.cacheReadTokens ?? 0),
    cacheWriteTokens: totals.cacheWriteTokens + (usage.cacheWriteTokens ?? 0),
    reasoningTokens: totals.reasoningTokens + (usage.reasoningTokens ?? 0),
  })
}

/** Count one tool result that reported an error, classified by its recorded code. */
function withToolResult(state: SessionFactsState, event: SessionEvent<'tool/result'>): SessionFactsState {
  const [block] = event.data.message.content
  if (block.isError !== true) return state
  const code = event.data.error?.code
  const tools = state.facts.tools
  const aborted = code === TOOL_ABORTED || code === TOOL_ABORTED_BEFORE_DISPATCH
  return withTools(state, {
    toolErrors: tools.toolErrors + 1,
    toolTimeouts: tools.toolTimeouts + (code === TOOL_TIMEOUT ? 1 : 0),
    toolAborts: tools.toolAborts + (aborted ? 1 : 0),
  })
}

/**
 * Fold one event into the accumulator.
 * @param state - the accumulator covering every prior event.
 * @param event - the next event in sequence order.
 * @returns the next accumulator; every event moves the log's time span, so the reference always changes.
 * @throws when the event is a goal or verification change the strict folds reject.
 */
export function applySessionFacts(state: SessionFactsState, event: SessionEvent): SessionFactsState {
  const timed = withEventTime(state, event)
  if (isOutcomeEvent(event)) {
    const outcomeEvents = [...timed.outcomeEvents, event]
    return { ...timed, outcomeEvents, facts: { ...timed.facts, outcome: foldOutcome(outcomeEvents) } }
  }
  switch (event.type) {
    case 'turn/start':
      return withEfficiency(timed, { turns: timed.facts.efficiency.turns + 1 })
    case 'step/start':
      return withEfficiency(timed, { steps: timed.facts.efficiency.steps + 1 })
    case 'assistant/message':
      return withUsage(timed, event)
    case 'environment/run':
      return withStamp(timed, event)
    case 'request/header':
      return withIdentity(timed, {
        requestProvider: event.data.header.config.provider,
        requestModel: event.data.header.config.model,
      })
    case 'tool/call': {
      const tools = timed.facts.tools
      const calls = tools.toolCallsByName[event.data.name] ?? 0
      return withTools(timed, {
        toolCalls: tools.toolCalls + 1,
        toolCallsByName: { ...tools.toolCallsByName, [event.data.name]: calls + 1 },
      })
    }
    case 'tool/result':
      return withToolResult(timed, event)
    // SessionEventMap is merge-extensible: every other event moves only the time span.
    default:
      return timed
  }
}

/**
 * Fold a whole session log into its accumulator.
 * @param events - the session's contiguous event log.
 * @returns the accumulator covering every event.
 * @throws when a goal or verification change violates its strict stream.
 */
export function foldSessionFactsState(events: readonly SessionEvent[]): SessionFactsState {
  let state = emptySessionFactsState()
  for (const event of events) state = applySessionFacts(state, event)
  return state
}

/**
 * Fold one persisted session into its facts record.
 * @param meta - the stored session header.
 * @param events - the session's contiguous event log.
 * @returns the four fact groups with the header's identity; deterministic for the same inputs.
 * @throws when a goal or verification change violates its strict stream.
 */
export function foldSessionFacts(meta: SessionHeader, events: readonly SessionEvent[]): SessionFactsRecord {
  const facts = foldSessionFactsState(events).facts
  return { ...facts, identity: { sessionId: meta.id, createdAt: meta.createdAt, ...facts.identity } }
}

/**
 * Pure fold of session facts into scoreboard rows: one row per model route,
 * environment, isolation level, and held-out split, each carrying the unbiased
 * pass@k estimate over the repetition batches its sessions belong to.
 *
 * @module @deepseek-ai/dsh-scorekeeper
 */

import type {
  EnvironmentStats,
  LeaderboardFilter,
  PassAtK,
  ScoreboardRow,
  SessionFactsEnvironment,
  SessionFactsRecord,
} from './types.ts'

/** Sample and certified counts of one repetition batch inside one row. */
interface Batch {
  /** Sessions of the row that carried this batch identity. */
  samples: number
  /** How many of them certified. */
  certified: number
}

/** One row under construction. */
interface RowAccumulator {
  readonly environment: SessionFactsEnvironment
  runs: number
  errors: number
  certified: number
  attemptSum: number
  inputTokens: number
  outputTokens: number
  readonly batches: Map<string, Batch>
}

/** Rows folded from a set of session facts, with what the fold set aside. */
export interface ScoreboardFold {
  /** One row per cell, in first-appearance order. */
  readonly rows: readonly ScoreboardRow[]
  /** Stamped records the filter's group or held-out condition excluded. */
  readonly excluded: number
  /** Records whose log carries no `environment/run` stamp, so no row can name their cell. */
  readonly unstamped: number
}

/** Key of the row one stamped session belongs to. */
function rowKey(environment: SessionFactsEnvironment): string {
  return [
    environment.provider,
    environment.model,
    environment.environmentId,
    environment.isolation,
    String(environment.heldOut),
  ].join('�')
}

/**
 * Unbiased pass@k over one batch: the chance that a draw of `k` of its `n`
 * sessions holds at least one certified session, `1 - C(n - c, k) / C(n, k)`
 * evaluated as a product so no factorial overflows.
 * @param n - sessions in the batch, at least `k`.
 * @param c - how many of them certified.
 * @param k - repetitions drawn.
 * @returns the estimate between `0` and `1`.
 */
export function unbiasedPassAtK(n: number, c: number, k: number): number {
  if (n - c < k) return 1
  let miss = 1
  for (let index = 0; index < k; index += 1) miss *= (n - c - index) / (n - index)
  return 1 - miss
}

/** Estimate pass@k for every configured `k` a batch of the row reached. */
function statsOf(batches: ReadonlyMap<string, Batch>, ks: readonly number[]): EnvironmentStats {
  let samples = 0
  for (const batch of batches.values()) samples += batch.samples
  const passAtK: PassAtK[] = []
  for (const k of ks) {
    let total = 0
    let groups = 0
    for (const batch of batches.values()) {
      if (batch.samples < k) continue
      total += unbiasedPassAtK(batch.samples, batch.certified, k)
      groups += 1
    }
    if (groups > 0) passAtK.push({ k, value: total / groups, groups })
  }
  return { groups: batches.size, samples, passAtK }
}

/** Whether one stamped session passes the filter's group and held-out conditions. */
function matches(filter: LeaderboardFilter, environment: SessionFactsEnvironment): boolean {
  if (filter.group !== undefined && environment.group !== filter.group) return false
  return filter.heldOut === undefined || environment.heldOut === filter.heldOut
}

/** Add one stamped session to its row. */
function accumulate(rows: Map<string, RowAccumulator>, record: SessionFactsRecord, environment: SessionFactsEnvironment): void {
  const key = rowKey(environment)
  const row = rows.get(key) ?? {
    environment,
    runs: 0,
    errors: 0,
    certified: 0,
    attemptSum: 0,
    inputTokens: 0,
    outputTokens: 0,
    batches: new Map<string, Batch>(),
  }
  rows.set(key, row)
  const outcome = record.outcome
  if (outcome.runsRecorded === 0) row.errors += 1
  else {
    row.runs += 1
    row.attemptSum += outcome.runsRecorded
  }
  if (outcome.certified) row.certified += 1
  row.inputTokens += record.efficiency.inputTokens
  row.outputTokens += record.efficiency.outputTokens
  if (environment.group === undefined) return
  const batch = row.batches.get(environment.group) ?? { samples: 0, certified: 0 }
  row.batches.set(environment.group, batch)
  batch.samples += 1
  if (outcome.certified) batch.certified += 1
}

/** Close one accumulator into its row. */
function finish(row: RowAccumulator, ks: readonly number[]): ScoreboardRow {
  return {
    provider: row.environment.provider,
    model: row.environment.model,
    environmentId: row.environment.environmentId,
    environmentKind: row.environment.environmentKind,
    heldOut: row.environment.heldOut,
    isolation: row.environment.isolation,
    runs: row.runs,
    errors: row.errors,
    certified: row.certified,
    certificateRate: row.runs === 0 ? 0 : row.certified / row.runs,
    attemptsMean: row.runs === 0 ? 0 : row.attemptSum / row.runs,
    inputTokens: row.inputTokens,
    outputTokens: row.outputTokens,
    stats: statsOf(row.batches, ks),
  }
}

/**
 * Fold session facts into scoreboard rows.
 * @param records - one facts record per session, in the order the rows appear.
 * @param filter - the group and held-out conditions a stamped record must meet.
 * @param ks - the pass@k draws to estimate, ascending.
 * @returns the rows plus the counts of excluded and unstamped records.
 */
export function foldScoreboard(
  records: readonly SessionFactsRecord[],
  filter: LeaderboardFilter,
  ks: readonly number[],
): ScoreboardFold {
  const rows = new Map<string, RowAccumulator>()
  let excluded = 0
  let unstamped = 0
  for (const record of records) {
    const environment = record.identity.environment
    if (environment === undefined) {
      unstamped += 1
      continue
    }
    if (!matches(filter, environment)) {
      excluded += 1
      continue
    }
    accumulate(rows, record, environment)
  }
  return { rows: [...rows.values()].map(row => finish(row, ks)), excluded, unstamped }
}

/**
 * Scorekeeper: the session log as the dataset. A `sessionFacts` projection
 * unit serves one live session's facts, and `ctx.scorekeeper` folds the same
 * facts out of persisted logs — one record per session, a scoreboard grouped
 * by model route, environment, isolation, and held-out split, and a JSONL
 * export. The service reads through the session persistence seam and writes no
 * session event. The
 * [scorekeeper Agent Note](../../../.agents/notes/proposed/architecture/2026-09-05-scorekeeper.md)
 * owns the design rationale.
 * @module @deepseek-ai/dsh-scorekeeper
 */

import { Context, Service } from '@deepseek-ai/cordis'
import z from '@deepseek-ai/schemastery'
import { z as zod } from 'zod'
import type { ZodType } from 'zod'
import type { SessionEvent, SessionId } from '@deepseek-ai/dsh-session'
// Type-only: resolves ctx.sessionPersistence.
import type {} from '@deepseek-ai/dsh-session-persistence'
// Type-only: resolves ctx.sessionProjections for the optional unit child.
import type {} from '@deepseek-ai/dsh-session-projection'
import { applySessionFacts, emptySessionFactsState, foldSessionFacts } from './fold.ts'
import type { SessionFactsState } from './fold.ts'
import { foldScoreboard } from './scoreboard.ts'
import type {
  FactsExportReport,
  FactsExportRequest,
  LeaderboardFilter,
  ScoreboardBatch,
  ScorekeeperSkip,
  SessionFacts,
  SessionFactsRecord,
} from './types.ts'

export type * from './types.ts'
export {
  applySessionFacts,
  emptySessionFactsState,
  foldSessionFacts,
  foldSessionFactsState,
} from './fold.ts'
export type { SessionFactsState } from './fold.ts'
export { foldScoreboard, unbiasedPassAtK } from './scoreboard.ts'
export type { ScoreboardFold } from './scoreboard.ts'

declare module '@deepseek-ai/cordis' {
  interface Context {
    scorekeeper: ScorekeeperService
  }
}

/** Wire payload schema of one run stamp's fields inside the projection. */
const environmentSchema = zod.object({
  environmentId: zod.string().min(1),
  environmentKind: zod.string().min(1),
  heldOut: zod.boolean(),
  repetition: zod.number().int().nonnegative(),
  group: zod.string().min(1).optional(),
  contentSha256: zod.string().min(1),
  provider: zod.string().min(1),
  model: zod.string().min(1),
  isolation: zod.union([zod.literal('none'), zod.literal('process'), zod.literal('host')]),
})

// Cast for the optional values: under exactOptionalPropertyTypes zod infers
// `T | undefined` where the interface declares absent-or-present fields.
/** Wire payload schema of the `sessionFacts` projection (the four fact groups). */
const sessionFactsSchema: ZodType<SessionFacts> = zod.object({
  identity: zod.object({
    environment: environmentSchema.optional(),
    requestProvider: zod.string().min(1).optional(),
    requestModel: zod.string().min(1).optional(),
  }),
  outcome: zod.object({
    reward: zod.union([zod.literal(1), zod.literal(0), zod.null()]),
    rewardBasis: zod.union([
      zod.literal('certificate'),
      zod.literal('uncertified-completion'),
      zod.literal('none'),
    ]),
    certified: zod.boolean(),
    certificateRevision: zod.number().int().positive().optional(),
    runsRecorded: zod.number().int().nonnegative(),
    attempts: zod.number().int().nonnegative(),
    directives: zod.number().int().nonnegative(),
    relaxations: zod.number().int().nonnegative(),
    goalPhase: zod.union([
      zod.literal('active'),
      zod.literal('paused'),
      zod.literal('blocked'),
      zod.literal('complete'),
    ]).optional(),
    goalRoundsStarted: zod.number().int().nonnegative(),
    goalRoundsCap: zod.number().int().positive().optional(),
    budgetBreachCap: zod.string().min(1).optional(),
  }),
  efficiency: zod.object({
    turns: zod.number().int().nonnegative(),
    steps: zod.number().int().nonnegative(),
    inputTokens: zod.number().int().nonnegative(),
    outputTokens: zod.number().int().nonnegative(),
    cacheReadTokens: zod.number().int().nonnegative(),
    cacheWriteTokens: zod.number().int().nonnegative(),
    reasoningTokens: zod.number().int().nonnegative(),
    wallMs: zod.number().int().nonnegative(),
  }),
  tools: zod.object({
    toolCalls: zod.number().int().nonnegative(),
    toolCallsByName: zod.record(zod.string(), zod.number().int().nonnegative()),
    toolErrors: zod.number().int().nonnegative(),
    toolTimeouts: zod.number().int().nonnegative(),
    toolAborts: zod.number().int().nonnegative(),
  }),
}) as unknown as ZodType<SessionFacts>

/**
 * Projection-grade transition of the `sessionFacts` unit. The outcome group is
 * decided by the strict goal and verification folds, so a change they reject
 * leaves the value at its previous state instead of tearing the read side;
 * validating a written change is the write side's job.
 * @param state - the accumulator covering all prior events.
 * @param event - the next committed session event.
 * @returns the next accumulator, or the same reference when the change was rejected.
 */
export function applySessionFactsProjection(state: SessionFactsState, event: SessionEvent): SessionFactsState {
  try {
    return applySessionFacts(state, event)
  } catch (_rejectedOutcomeChange) {
    // The goal and verification services own the two streams that can throw
    // here; their own invariant companions reject a malformed change at source.
    return state
  }
}

/** Deployment choices of the scorekeeper, validated from `cordis.yml`. */
export interface Config {
  /** Repetition draws the scoreboard estimates pass@k for. */
  passAtK?: number[]
}

/** The scorekeeper's choices with every default applied. */
export interface ResolvedConfig {
  /** Ascending, de-duplicated pass@k draws. */
  readonly passAtK: readonly number[]
}

/**
 * Apply the scorekeeper's defaults to a validated config.
 * @param config - validated deployment config.
 * @returns the resolved choices: pass@1 alone unless configured otherwise.
 */
export function resolveConfig(config: Config): ResolvedConfig {
  return { passAtK: [...new Set(config.passAtK ?? [1])].sort((left, right) => left - right) }
}

/** Render a read or fold failure for a report without trusting the thrown value. */
function reasonOf(error: unknown): string {
  return error instanceof Error ? error.message : String(error)
}

/** One session's facts, or the failure that prevented folding them. */
type FactsOutcome = { readonly record: SessionFactsRecord } | { readonly skip: ScorekeeperSkip }

/** Scorekeeper (`ctx.scorekeeper`): session facts, the scoreboard, and the facts export. */
export class ScorekeeperService extends Service {
  static inject = ['sessionPersistence']

  static Config: z<Config> = z.object({
    passAtK: z.array(z.natural().min(1)).default([1]),
  })

  private readonly resolved: ResolvedConfig

  constructor(ctx: Context, config: Config = {}) {
    super(ctx, 'scorekeeper')
    this.resolved = resolveConfig(config)
    // The `sessionFacts` projection unit activates only when a projection
    // registry is composed; a headless assembly keeps the service verbs alone.
    ctx.inject(['sessionProjections'], (projectionCtx) => {
      projectionCtx.sessionProjections.register<'sessionFacts', SessionFactsState>({
        key: 'sessionFacts',
        schema: sessionFactsSchema,
        init: emptySessionFactsState,
        apply: applySessionFactsProjection,
        view: state => state.facts,
        stateVersion: 1,
      })
    })
  }

  /**
   * Fold one persisted session into its facts record.
   * @param sessionId - the persisted session to read.
   * @returns the four fact groups with the stored header's identity.
   * @throws when the session cannot be read, or its goal or verification stream is malformed.
   */
  async facts(sessionId: SessionId): Promise<SessionFactsRecord> {
    const { meta, events } = await this.ctx.sessionPersistence.inspect(sessionId)
    return foldSessionFacts(meta, events)
  }

  /**
   * Fold a scoreboard from persisted session logs, one row per model route,
   * environment, isolation level, and held-out split. A session that cannot be
   * read or folded is reported and the fold continues.
   * @param filter - the sessions to fold and the group and held-out conditions a stamped session must meet.
   * @returns the rows with their pass@k statistics, the counts of excluded, unstamped, and skipped sessions, and the fold time.
   */
  async leaderboard(filter: LeaderboardFilter = {}): Promise<ScoreboardBatch> {
    const sessions = await this.sessionsOf(filter.sessions)
    const records: SessionFactsRecord[] = []
    const skipped: ScorekeeperSkip[] = []
    for (const sessionId of sessions) {
      const outcome = await this.factsOf(sessionId)
      if ('skip' in outcome) skipped.push(outcome.skip)
      else records.push(outcome.record)
    }
    const fold = foldScoreboard(records, filter, this.resolved.passAtK)
    return {
      rows: fold.rows,
      sessions: sessions.length,
      excluded: fold.excluded,
      unstamped: fold.unstamped,
      skipped,
      computedAt: Date.now(),
    }
  }

  /**
   * Write one JSON line per session's facts record. A session that cannot be
   * read or folded is reported and the export continues; the sink is closed
   * exactly once when every session has been handled.
   * @param request - sessions to export and the destination sink.
   * @returns counts of sessions, written lines, and skips with reasons.
   */
  async exportFacts(request: FactsExportRequest): Promise<FactsExportReport> {
    const sessions = await this.sessionsOf(request.sessions)
    const skipped: ScorekeeperSkip[] = []
    let exported = 0
    try {
      for (const sessionId of sessions) {
        const outcome = await this.factsOf(sessionId)
        if ('skip' in outcome) {
          skipped.push(outcome.skip)
          continue
        }
        await request.sink.write(`${JSON.stringify(outcome.record)}\n`)
        exported += 1
      }
    } finally {
      await request.sink.close()
    }
    return { sessions: sessions.length, exported, skipped }
  }

  /** The requested sessions, or every persisted session when none were named. */
  private async sessionsOf(sessions?: readonly SessionId[]): Promise<readonly SessionId[]> {
    return sessions ?? (await this.ctx.sessionPersistence.list()).map(header => header.id)
  }

  /** Read and fold one session, keeping a read or fold failure as a skip. */
  private async factsOf(sessionId: SessionId): Promise<FactsOutcome> {
    try {
      return { record: await this.facts(sessionId) }
    } catch (error: unknown) {
      return { skip: { sessionId, reason: reasonOf(error) } }
    }
  }
}

export default ScorekeeperService

/**
 * Package-owned invariant: the outcome group the session-facts fold publishes
 * is what the log itself says. Two relations are recomputed from the durable
 * events on every goal, verification, or budget change: `runsRecorded` equals
 * the number of `verification/run` events in the log, and `certified` agrees
 * with the trajectory reward fold's verdict, so the verification fold and the
 * reward fold can never disagree inside one record.
 *
 * @module @deepseek-ai/dsh-scorekeeper/invariant
 */

import type { Context } from '@deepseek-ai/cordis'
import type { InvariantFailure, InvariantInstaller } from '@deepseek-ai/dsh-invariants'
import type { Session, SessionEvent } from '@deepseek-ai/dsh-session'
import { foldSessionFactsState } from './fold.ts'
import type { SessionFactsOutcome } from './types.ts'

const PACKAGE_NAME = '@deepseek-ai/dsh-scorekeeper'

/** Cordis companion plugin name. */
export const name = 'scorekeeper-invariant'
/** Service required before the companion can reserve package ownership. */
export const inject = ['invariants']

/** Whether one event can change the outcome group. */
function decidesOutcome(event: SessionEvent): boolean {
  return event.type === 'goal/change' || event.type.startsWith('verification/')
}

/** Fold the outcome group over a log, leaving a malformed stream to its own owner. */
function outcomeOf(events: readonly SessionEvent[]): SessionFactsOutcome | undefined {
  try {
    return foldSessionFactsState(events).facts.outcome
  } catch (_malformedOutcomeStream) {
    // The goal and verification companions own their own malformed streams;
    // reporting the same event twice would attribute it to this package.
    return undefined
  }
}

/** Validate one candidate event against the durable prefix that precedes it. */
function validateEvent(prior: readonly SessionEvent[], event: SessionEvent, fail: InvariantFailure): void {
  if (!decidesOutcome(event)) return
  const events = [...prior, event]
  const outcome = outcomeOf(events)
  if (outcome === undefined) return
  const runs = events.filter(candidate => candidate.type === 'verification/run').length
  if (outcome.runsRecorded !== runs) {
    fail(`session event ${event.seq} leaves sessionFacts runsRecorded ${outcome.runsRecorded} while the log holds ${runs} verification/run events`)
  }
  if (outcome.certified !== (outcome.reward === 1)) {
    fail(`session event ${event.seq} leaves sessionFacts certified ${String(outcome.certified)} while the reward fold decided ${String(outcome.reward)}`)
  }
}

/** Check existing sessions and every candidate event before Session publishes it. */
const install: InvariantInstaller = Object.assign((ctx: Context, fail: InvariantFailure) => {
  for (const session of ctx.sessions.list()) {
    const prior: SessionEvent[] = []
    for (const event of session.events) {
      validateEvent(prior, event, fail)
      prior.push(event)
    }
  }
  /* jscpd:ignore-start -- package companions share dispatch and registration plumbing */
  ctx.on('internal/dispatch', (_mode, eventName, args) => {
    if (eventName !== 'session/event') return
    const [session, event] = args as [Session, SessionEvent]
    validateEvent(session.events, event, fail)
  }, { global: true })
}, { inject: ['sessions'] })

/**
 * Register the session-facts invariant companion.
 * @param ctx - Cordis context carrying the invariant service.
 * @returns the installed registration's disposer after setup succeeds.
 */
export const apply = (ctx: Context): Promise<() => void> =>
  Promise.resolve(ctx.invariants.register(PACKAGE_NAME, install))
/* jscpd:ignore-end */

/**
 * Package-owned invariant: a facts record states what its own log says. Three
 * relations are recomputed from the durable events on every stamp, goal, or
 * verification change — `runsRecorded` equals the number of `verification/run`
 * events, `certified` agrees with the reward the trajectory fold decided, and
 * a certificate's isolation equals the isolation its `environment/run` stamp
 * declared, so a scoreboard row keyed by the stamp can never blend a
 * certificate earned under a different isolation level.
 *
 * @module @deepseek-ai/dsh-scorekeeper/invariant
 */

import type { Context } from '@deepseek-ai/cordis'
import type { InvariantFailure, InvariantInstaller } from '@deepseek-ai/dsh-invariants'
import type { Session, SessionEvent } from '@deepseek-ai/dsh-session'
import { foldVerification } from '@deepseek-ai/dsh-verification'
import { foldSessionFactsState } from './fold.ts'
import type { SessionFacts } from './types.ts'

const PACKAGE_NAME = '@deepseek-ai/dsh-scorekeeper'

/** Cordis companion plugin name. */
export const name = 'scorekeeper-invariant'
/** Service required before the companion can reserve package ownership. */
export const inject = ['invariants']

/** Event types that can change one of the checked relations. */
const DECIDING_EVENT_TYPES: ReadonlySet<string> = new Set([
  'environment/run',
  'goal/change',
  'verification/standard',
  'verification/relaxation',
  'verification/run',
  'verification/certificate',
  'verification/directive',
])

/**
 * Recompute every checked relation of one facts record against its log.
 * @param facts - the facts folded from `events`.
 * @param events - the durable events the record covers, in sequence order.
 * @returns one message per broken relation; empty when the record agrees with the log.
 */
export function factsDisagreements(facts: SessionFacts, events: readonly SessionEvent[]): string[] {
  const messages: string[] = []
  const outcome = facts.outcome
  const runs = events.filter(event => event.type === 'verification/run').length
  if (outcome.runsRecorded !== runs) {
    messages.push(`records runsRecorded ${outcome.runsRecorded} while the log holds ${runs} verification/run events`)
  }
  if (outcome.certified !== (outcome.reward === 1)) {
    messages.push(`records certified ${String(outcome.certified)} while the reward fold decided ${String(outcome.reward)}`)
  }
  const certificate = foldVerification(events).certificate
  const stamp = facts.identity.environment
  if (stamp !== undefined && certificate !== undefined && certificate.isolation !== stamp.isolation) {
    messages.push(`certifies at isolation "${certificate.isolation}" while its environment/run stamp declared "${stamp.isolation}"`)
  }
  return messages
}

/** Validate one candidate event against the durable prefix that precedes it. */
function validateEvent(prior: readonly SessionEvent[], event: SessionEvent, fail: InvariantFailure): void {
  if (!DECIDING_EVENT_TYPES.has(event.type)) return
  const events = [...prior, event]
  let facts: SessionFacts
  try {
    facts = foldSessionFactsState(events).facts
  } catch (_malformedOutcomeStream) {
    // The goal and verification companions own their own malformed streams;
    // reporting the same event here would attribute it to this package too.
    return
  }
  for (const message of factsDisagreements(facts, events)) fail(`session event ${event.seq} ${message}`)
}

/** Check existing sessions and every candidate event before Session publishes it. */
const install: InvariantInstaller = Object.assign((ctx: Context, fail: InvariantFailure) => {
  for (const session of ctx.sessions.list()) {
    const prior: SessionEvent[] = []
    for (const event of session.events) {
      validateEvent(prior, event, fail)
      prior.push(event)
    }
  }
  /* jscpd:ignore-start -- package companions share dispatch and registration plumbing */
  ctx.on('internal/dispatch', (_mode, eventName, args) => {
    if (eventName !== 'session/event') return
    const [session, event] = args as [Session, SessionEvent]
    validateEvent(session.events, event, fail)
  }, { global: true })
}, { inject: ['sessions'] })

/**
 * Register the session-facts invariant companion.
 * @param ctx - Cordis context carrying the invariant service.
 * @returns the installed registration's disposer after setup succeeds.
 */
export const apply = (ctx: Context): Promise<() => void> =>
  Promise.resolve(ctx.invariants.register(PACKAGE_NAME, install))
/* jscpd:ignore-end */

