/**
 * The pure session-facts fold: every field of the four groups comes from a
 * named event, the outcome group is decided by the goal, verification, and
 * reward folds that own those streams, and a malformed change fails the fold
 * loudly so a caller can report the session instead of publishing a wrong row.
 */

import { describe, expect, it } from 'vitest'
import { TOOL_TIMEOUT } from '@deepseek-ai/dsh-tool-call-timeout-policy'
import { TOOL_ABORTED, TOOL_ABORTED_BEFORE_DISPATCH } from '@deepseek-ai/dsh-tools'
import {
  applySessionFacts,
  emptySessionFactsState,
  foldSessionFacts,
  foldSessionFactsState,
} from '@deepseek-ai/dsh-scorekeeper'
import { cellLog, certificate, directive, goalChange, header, Log, runRecord, standard, stamp } from './log.ts'

describe('foldSessionFacts', () => {
  it('folds the empty log into zeroed groups carrying only the stored header identity', () => {
    expect(foldSessionFacts(header('empty'), [])).toEqual({
      identity: { sessionId: 'empty', createdAt: 500 },
      outcome: {
        reward: null,
        rewardBasis: 'none',
        certified: false,
        runsRecorded: 0,
        attempts: 0,
        directives: 0,
        relaxations: 0,
        goalRoundsStarted: 0,
      },
      efficiency: {
        turns: 0,
        steps: 0,
        inputTokens: 0,
        outputTokens: 0,
        cacheReadTokens: 0,
        cacheWriteTokens: 0,
        reasoningTokens: 0,
        wallMs: 0,
      },
      tools: { toolCalls: 0, toolCallsByName: {}, toolErrors: 0, toolTimeouts: 0, toolAborts: 0 },
    })
  })

  it('carries the run stamp, the certificate, and the turn and token counts of a certified cell', () => {
    const events = cellLog({ stamp: stamp({ group: 'batch-1', repetition: 2 }), certified: true, runs: 1 })
    const facts = foldSessionFacts(header('certified'), events)
    expect(facts.identity).toEqual({
      sessionId: 'certified',
      createdAt: 500,
      environment: {
        environmentId: 'smoke:round-trip',
        environmentKind: 'smoke',
        heldOut: false,
        repetition: 2,
        group: 'batch-1',
        contentSha256: 'c'.repeat(64),
        provider: 'cli-mock',
        model: 'cli-mock',
        isolation: 'none',
      },
      requestProvider: 'cli-mock',
      requestModel: 'cli-mock',
    })
    expect(facts.outcome).toEqual({
      reward: 1,
      rewardBasis: 'certificate',
      certified: true,
      certificateRevision: 1,
      runsRecorded: 1,
      attempts: 1,
      directives: 0,
      relaxations: 0,
      goalPhase: 'complete',
      goalRoundsCap: 7,
      goalRoundsStarted: 0,
    })
    expect(facts.efficiency).toMatchObject({ turns: 1, steps: 1, inputTokens: 12, outputTokens: 3 })
    // Ten events at one millisecond apart, from the stamp to the closing turn.
    expect(facts.efficiency.wallMs).toBe(events.length - 1)
  })

  it('scores a measured cell without a certificate as zero and counts every recorded run and directive', () => {
    const log = new Log()
    log.push('environment/run', stamp())
    log.push('goal/change', goalChange('create', 'active', 1))
    log.push('verification/standard', standard())
    log.push('verification/run', runRecord(1, 'fail'))
    log.push('verification/directive', directive())
    log.push('verification/run', runRecord(2, 'fail'))
    const facts = foldSessionFacts(header('measured'), log.events)
    expect(facts.outcome).toMatchObject({
      reward: 0,
      rewardBasis: 'certificate',
      certified: false,
      runsRecorded: 2,
      attempts: 2,
      directives: 1,
      goalPhase: 'active',
    })
    expect(facts.outcome.certificateRevision).toBeUndefined()
    expect(facts.identity.environment?.group).toBeUndefined()
    expect(facts.identity.requestProvider).toBeUndefined()
  })

  it('leaves a completion no standard measured undecided and counts the admitted rounds', () => {
    const log = new Log()
    log.push('goal/change', goalChange('create', 'active', 1))
    log.goalRound(1, 1)
    log.push('goal/change', goalChange('complete', 'complete', 2, 1))
    const facts = foldSessionFacts(header('unmeasured'), log.events)
    expect(facts.outcome).toMatchObject({
      reward: null,
      rewardBasis: 'uncertified-completion',
      certified: false,
      goalRoundsStarted: 1,
      goalPhase: 'complete',
    })
  })

  it('records the cap of the last budget breach', () => {
    const log = new Log()
    log.push('budget/breach', { cap: 'maxTotalTokens', measured: 9, limit: 4 })
    log.push('budget/breach', { cap: 'maxCostEur', measured: 2, limit: 1 })
    expect(foldSessionFacts(header('breached'), log.events).outcome.budgetBreachCap).toBe('maxCostEur')
  })

  it('sums every usage bucket an assistant message reports and ignores a message without usage', () => {
    const log = new Log()
    log.assistant({ inputTokens: 5, outputTokens: 2, cacheReadTokens: 7, cacheWriteTokens: 1, reasoningTokens: 4 })
    log.assistant({ inputTokens: 3, outputTokens: 1 })
    log.assistant()
    expect(foldSessionFacts(header('usage'), log.events).efficiency).toMatchObject({
      inputTokens: 8,
      outputTokens: 3,
      cacheReadTokens: 7,
      cacheWriteTokens: 1,
      reasoningTokens: 4,
    })
  })

  it('counts tool calls by name and classifies every recorded error code', () => {
    const log = new Log()
    log.push('tool/call', { turn: 1, step: 1, callId: 'c1', name: 'bash', arguments: '{}' })
    log.push('tool/call', { turn: 1, step: 1, callId: 'c2', name: 'bash', arguments: '{}' })
    log.push('tool/call', { turn: 1, step: 1, callId: 'c3', name: 'read', arguments: '{}' })
    log.toolResult('c1', false)
    log.toolResult('c2', true, TOOL_TIMEOUT)
    log.toolResult('c3', true, TOOL_ABORTED)
    log.toolResult('c4', true, TOOL_ABORTED_BEFORE_DISPATCH)
    log.toolResult('c5', true)
    expect(foldSessionFacts(header('tools'), log.events).tools).toEqual({
      toolCalls: 3,
      toolCallsByName: { bash: 2, read: 1 },
      toolErrors: 4,
      toolTimeouts: 1,
      toolAborts: 2,
    })
  })

  it('rejects a verification change the strict stream refuses', () => {
    const log = new Log()
    log.push('verification/certificate', certificate())
    expect(() => foldSessionFactsState(log.events)).toThrow('verification certificate requires a current standard')
  })

  it('leaves every other event to the log clock alone', () => {
    const state = applySessionFacts(emptySessionFactsState(), {
      type: 'turn/end',
      seq: 0,
      time: 1_000,
      data: { turn: 1, reason: { kind: 'completed' } },
    })
    expect(state.facts.efficiency.wallMs).toBe(0)
    expect(state.outcomeEvents).toEqual([])
  })
})

/**
 * The pure scoreboard fold: one row per model route, environment, isolation
 * level, and held-out split; a stamped session without a recorded run is an
 * error column rather than a missing row; and pass@k is estimated only over
 * the batches that hold at least `k` sessions.
 */

import { describe, expect, it } from 'vitest'
import { foldScoreboard, foldSessionFacts, unbiasedPassAtK } from '@deepseek-ai/dsh-scorekeeper'
import type { SessionFactsRecord } from '@deepseek-ai/dsh-scorekeeper'
import { cellLog, header, Log, stamp } from './log.ts'

/** One cell's facts record, as the service folds it out of persistence. */
function cell(id: string, options: {
  readonly certified: boolean
  readonly runs: number
  readonly group?: string
  readonly repetition?: number
  readonly heldOut?: boolean
  readonly environmentId?: string
  readonly isolation?: string
}): SessionFactsRecord {
  const overrides = {
    ...options.group === undefined ? {} : { group: options.group },
    ...options.repetition === undefined ? {} : { repetition: options.repetition },
    ...options.heldOut === undefined ? {} : { heldOut: options.heldOut },
    ...options.environmentId === undefined ? {} : { environmentId: options.environmentId },
    ...options.isolation === undefined ? {} : { isolation: options.isolation },
  }
  return foldSessionFacts(header(id), cellLog({ stamp: stamp(overrides), certified: options.certified, runs: options.runs }))
}

/** A session no runner stamped. */
function unstamped(id: string): SessionFactsRecord {
  const log = new Log()
  log.assistant({ inputTokens: 1, outputTokens: 1 })
  return foldSessionFacts(header(id), log.events)
}

describe('unbiasedPassAtK', () => {
  it('is one when fewer than k sessions missed and rises with the certified share otherwise', () => {
    expect(unbiasedPassAtK(4, 3, 2)).toBe(1)
    expect(unbiasedPassAtK(2, 1, 1)).toBe(0.5)
    expect(unbiasedPassAtK(4, 0, 2)).toBe(0)
    expect(unbiasedPassAtK(4, 1, 2)).toBeCloseTo(0.5, 10)
  })
})

describe('foldScoreboard', () => {
  it('folds one row per cell with its rates, token sums, and pass@k over each batch', () => {
    const records = [
      cell('a0', { certified: true, runs: 1, group: 'batch-1', repetition: 0 }),
      cell('a1', { certified: false, runs: 2, group: 'batch-1', repetition: 1 }),
      cell('b0', { certified: true, runs: 1, group: 'batch-2', repetition: 0 }),
      cell('c0', { certified: false, runs: 2, environmentId: 'smoke:unsatisfiable' }),
    ]
    const fold = foldScoreboard(records, {}, [1, 2, 3])
    expect(fold).toMatchObject({ excluded: 0, unstamped: 0 })
    expect(fold.rows).toHaveLength(2)
    expect(fold.rows[0]).toMatchObject({
      provider: 'cli-mock',
      model: 'cli-mock',
      environmentId: 'smoke:round-trip',
      environmentKind: 'smoke',
      heldOut: false,
      isolation: 'none',
      runs: 3,
      errors: 0,
      certified: 2,
      attemptsMean: 4 / 3,
      inputTokens: 36,
      outputTokens: 9,
    })
    expect(fold.rows[0]?.certificateRate).toBeCloseTo(2 / 3, 10)
    expect(fold.rows[0]?.stats).toEqual({
      groups: 2,
      samples: 3,
      passAtK: [
        { k: 1, value: 0.75, groups: 2 },
        { k: 2, value: 1, groups: 1 },
      ],
    })
    expect(fold.rows[1]).toMatchObject({ environmentId: 'smoke:unsatisfiable', runs: 1, certified: 0, certificateRate: 0 })
    expect(fold.rows[1]?.stats).toEqual({ groups: 0, samples: 0, passAtK: [] })
  })

  it('keeps a stamped session that recorded no run as an error column with zeroed rates', () => {
    const fold = foldScoreboard([cell('errored', { certified: false, runs: 0 })], {}, [1])
    expect(fold.rows[0]).toMatchObject({ runs: 0, errors: 1, certified: 0, certificateRate: 0, attemptsMean: 0 })
  })

  it('splits rows by isolation level and by the held-out flag', () => {
    const fold = foldScoreboard([
      cell('none', { certified: true, runs: 1 }),
      cell('host', { certified: true, runs: 1, isolation: 'host' }),
      cell('reserved', { certified: true, runs: 1, heldOut: true }),
    ], {}, [1])
    expect(fold.rows.map(row => [row.isolation, row.heldOut])).toEqual([['none', false], ['host', false], ['none', true]])
  })

  it('excludes stamped sessions the group and held-out conditions reject, and rows no stamp names', () => {
    const records = [
      cell('kept', { certified: true, runs: 1, group: 'batch-1' }),
      cell('other-batch', { certified: true, runs: 1, group: 'batch-2' }),
      cell('reserved', { certified: true, runs: 1, group: 'batch-1', heldOut: true }),
      unstamped('no-stamp'),
    ]
    const fold = foldScoreboard(records, { group: 'batch-1', heldOut: false }, [1])
    expect(fold).toMatchObject({ excluded: 2, unstamped: 1 })
    expect(fold.rows).toHaveLength(1)
    expect(fold.rows[0]?.runs).toBe(1)
  })
})

